                                                                                                                                                                                                                                                                                                                                                module mnist_ann (
                                                                                                                                                                                                                                                                                                                                                    input  wire clk,
                                                                                                                                                                                                                                                                                                                                                    input  wire reset,
                                                                                                                                                                                                                                                                                                                                                    input  wire start,
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // One pixel value supplied according to pixel_index
                                                                                                                                                                                                                                                                                                                                                    input  wire signed [15:0] pixel_in,
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // Tells outside logic which MNIST pixel is currently needed
                                                                                                                                                                                                                                                                                                                                                    output wire [9:0] pixel_index,
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // Final predicted digit
                                                                                                                                                                                                                                                                                                                                                    output reg [3:0] predicted_digit,
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // High for one clock when the whole ANN is finished
                                                                                                                                                                                                                                                                                                                                                    output reg done
                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Hidden layer signals
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg hidden_start;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire hidden_done;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire [4:0] hidden_neuron_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire signed [15:0] hidden_value;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire [4:0] hidden_read_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Output layer signals
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg output_start;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire output_done;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire [3:0] output_neuron_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg [3:0] output_read_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    wire signed [47:0] output_score;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Argmax registers
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg [3:0] argmax_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg signed [47:0] max_score;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Controller states
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    localparam IDLE         = 3'd0;
                                                                                                                                                                                                                                                                                                                                                    localparam RUN_HIDDEN   = 3'd1;
                                                                                                                                                                                                                                                                                                                                                    localparam START_OUTPUT = 3'd2;
                                                                                                                                                                                                                                                                                                                                                    localparam RUN_OUTPUT   = 3'd3;
                                                                                                                                                                                                                                                                                                                                                    localparam ARGMAX_INIT  = 3'd4;
                                                                                                                                                                                                                                                                                                                                                    localparam ARGMAX_RUN   = 3'd5;
                                                                                                                                                                                                                                                                                                                                                    localparam FINISHED     = 3'd6;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    reg [2:0] state;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Hidden layer
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    hidden_layer hidden_layer_inst (
                                                                                                                                                                                                                                                                                                                                                        .clk(clk),
                                                                                                                                                                                                                                                                                                                                                        .reset(reset),
                                                                                                                                                                                                                                                                                                                                                        .start(hidden_start),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .pixel_in(pixel_in),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .read_index(hidden_read_index),
                                                                                                                                                                                                                                                                                                                                                        .hidden_out(hidden_value),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .pixel_index(pixel_index),
                                                                                                                                                                                                                                                                                                                                                        .neuron_index(hidden_neuron_index),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .done(hidden_done)
                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Output layer
                                                                                                                                                                                                                                                                                                                                                    //
                                                                                                                                                                                                                                                                                                                                                    // output_layer chooses which hidden output it needs.
                                                                                                                                                                                                                                                                                                                                                    // That same index is connected back into hidden_layer.
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    output_layer output_layer_inst (
                                                                                                                                                                                                                                                                                                                                                        .clk(clk),
                                                                                                                                                                                                                                                                                                                                                        .reset(reset),
                                                                                                                                                                                                                                                                                                                                                        .start(output_start),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .hidden_in(hidden_value),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .hidden_read_index(hidden_read_index),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .read_index(output_read_index),
                                                                                                                                                                                                                                                                                                                                                        .score_out(output_score),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .neuron_index(output_neuron_index),
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        .done(output_done)
                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                    // Main ANN controller
                                                                                                                                                                                                                                                                                                                                                    // ------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    always @(posedge clk) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        if (reset) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            hidden_start     <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                            output_start     <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            output_read_index <= 4'd0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            argmax_index     <= 4'd0;
                                                                                                                                                                                                                                                                                                                                                            max_score        <= 48'sd0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            predicted_digit  <= 4'd0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            done             <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            state            <= IDLE;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        else begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            // Start pulses default low
                                                                                                                                                                                                                                                                                                                                                            hidden_start <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                            output_start <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            // done is also a one-clock pulse
                                                                                                                                                                                                                                                                                                                                                            done <= 1'b0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            case (state)
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Wait for external start
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                IDLE: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    if (start) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        hidden_start <= 1'b1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        state <= RUN_HIDDEN;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Wait until all 32 hidden neurons are finished
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                RUN_HIDDEN: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    if (hidden_done) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        state <= START_OUTPUT;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Start the 10-neuron output layer
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                START_OUTPUT: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    output_start <= 1'b1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    state <= RUN_OUTPUT;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Wait until all 10 output scores are ready
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                RUN_OUTPUT: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    if (output_done) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        output_read_index <= 4'd0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        state <= ARGMAX_INIT;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Initialize argmax with output score 0
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                ARGMAX_INIT: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    max_score       <= output_score;
                                                                                                                                                                                                                                                                                                                                                                    predicted_digit <= 4'd0;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    argmax_index     <= 4'd1;
                                                                                                                                                                                                                                                                                                                                                                    output_read_index <= 4'd1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    state <= ARGMAX_RUN;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Compare scores 1 through 9
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                ARGMAX_RUN: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    if (output_score > max_score) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        max_score       <= output_score;
                                                                                                                                                                                                                                                                                                                                                                        predicted_digit <= argmax_index;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    if (argmax_index == 4'd9) begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        state <= FINISHED;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    else begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        argmax_index <= argmax_index + 1'b1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                        output_read_index
                                                                                                                                                                                                                                                                                                                                                                            <= output_read_index + 1'b1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                // Full ANN finished
                                                                                                                                                                                                                                                                                                                                                                // ------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                FINISHED: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    done <= 1'b1;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    state <= IDLE;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                default: begin
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                    state <= IDLE;
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                            endcase
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                        end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                    end
                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                endmodule
